function moyennePonderee(notes) {
  if (!notes || notes.length === 0) return 0;

  let somme = 0;
  let totalCoeff = 0;

  for (const note of notes) {
    somme += note.valeur * note.coeff;
    totalCoeff += note.coeff;
  }

  if (totalCoeff === 0) return 0;
  return somme / totalCoeff;
}
