function optimisationExtreme(arr, target) {
  const seen = new Set();

  for (const num of arr) {
    const complement = target - num;

    if (seen.has(complement)) {
      return true;
    }

    seen.add(num);
  }

  return false;
}

function fusionnerIntervalles(tab) {
    if (tab.length === 0) return [];

    tab.sort((a, b) => a[0] - b[0]);

    const merged = [tab[0]];
    for (let i = 1; i < tab.length; i++) {
        const current = tab[i];
        const last = merged[merged.length - 1];

        if (current[0] <= last[1]) {
            last[1] = Math.max(last[1], current[1]);
        } else {
            merged.push(current);
        }
    }
    return merged;
}

function prefixeCommun(tab) {
    if (tab.length === 0) return '';

    let minLen = Math.min(...tab.map(s => s.length));
    let result = '';

    for (let i = 0; i < minLen; i++) {
        const char = tab[0][i];
        if (tab.every(s => s[i] === char)) {
            result += char;
        } else {
            break;
        }
    }

    return result;
}

function nombreDeBits1(n) {
    let count = 0;
    while (n > 0) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

function medianeDeuxTries(a, b) {
  const lenA = a.length;
  const lenB = b.length;

  // Ensure we binary search on the smaller array
  if (lenA > lenB) return medianeDeuxTries(b, a);

  let lo = 0;
  let hi = lenA;

  while (lo <= hi) {
    const i = Math.floor((lo + hi) / 2); // partition in A
    const j = lenA + lenB - i - 1;        // partition in B

    const maxLeftA = i === 0 ? -Infinity : a[i - 1];
    const minRightA = i === lenA ? Infinity : a[i];

    const maxLeftB = j === 0 ? -Infinity : b[j - 1];
    const minRightB = j === lenB ? Infinity : b[j];

    if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
      // Found the correct partition
      return Math.max(maxLeftA, maxLeftB);
    } else if (maxLeftA > minRightB) {
      hi = i - 1;
    } else {
      lo = i + 1;
    }
  }

  // Should never reach here for valid inputs
  return NaN;
}

function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;

    const tails = [];

    for (const num of tab) {
        let left = 0, right = tails.length;

        while (left < right) {
            const mid = Math.floor((left + right) / 2);
            if (tails[mid] < num) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        tails[left] = num;
    }

    return tails.length;
}
